248	        // 墓碑历史版本同样不带业务字段
249	        getVersion("obs-1", 3)
250	                .andExpect(status().isOk())
251	                .andExpect(jsonPath("$.deleted").value(true))
252	                .andExpect(jsonPath("$.location").doesNotExist());
253	        // 历史版本仍可读取业务字段
254	        getVersion("obs-1", 2)
