261	    @Test
262	    void deleteWithMismatchedVersionReturns409() throws Exception {
263	        create("req-d4", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
264	        delete("req-d5", "obs-1", 7)
265	                .andExpect(status().isConflict())
