274	        create("req-d6", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
275	        delete("req-d7", "obs-1", 1).andExpect(status().isOk());
276	        merge("req-d8", "obs-1", 1, "站点B", "2.0", "备注")
277	                .andExpect(status().isGone());
278	        delete("req-d9", "obs-1", 2)
279	                .andExpect(status().isGone());
280	        // 墓碑不被复活
281	        getCurrent("obs-1")
282	                .andExpect(jsonPath("$.deleted").value(true))
283	                .andExpect(jsonPath("$.version").value(2));
284	        assertThat(versionCount("obs-1")).isEqualTo(2);
