287	    @Test
288	    void deleteOnMissingObservationReturns404() throws Exception {
289	        delete("req-d10", "obs-x", 1).andExpect(status().isNotFound());
290	    }
291	
292	    // ---------- 查询 ----------
293	
294	    @Test
295	    void getMissingObservationReturns404() throws Exception {
296	        getCurrent("obs-x").andExpect(status().isNotFound());
297	        getVersion("obs-x", 1).andExpect(status().isNotFound());
