300	    @Test
301	    void getMissingVersionReturns404() throws Exception {
302	        create("req-q1", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
303	        getVersion("obs-1", 5).andExpect(status().isNotFound());
304	    }
305	
306	    // ---------- 幂等 ----------
307	
308	    @Test
309	    void sameRequestIdAndParamsReplaysOriginalResult() throws Exception {
310	        create("req-i1", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
311	        // 同键同参重放：返回原成功结果，不产生新版本
312	        create("req-i1", "obs-1", "站点A", "1.0", "备注")
313	                .andExpect(status().isCreated())
314	                .andExpect(jsonPath("$.version").value(1));
315	        assertThat(versionCount("obs-1")).isEqualTo(1);
316	
