21	/**
22	 * 冲突解决并发边界测试：真实并发提交，验证只有匹配实际当前版本者成功、
23	 * 解决与删除竞争不覆盖新版本或复活墓碑、同 resolutionId 并发重放只生成一条记录。
24	 */
25	@SpringBootTest
26	class ResolutionConcurrencyTest {
27	
28	    @Autowired
29	    private ObservationService observationService;
30	
31	    @Autowired
32	    private JdbcTemplate jdbcTemplate;
33	
34	    @BeforeEach
35	    void cleanDatabase() {
36	        jdbcTemplate.update("DELETE FROM conflict_resolution");
37	        jdbcTemplate.update("DELETE FROM request_log");
38	        jdbcTemplate.update("DELETE FROM observation_version");
39	        jdbcTemplate.update("DELETE FROM observation_current");
40	    }
