75	        try {
76	            observationService.merge(observationId, new MergeObservationRequest(
77	                    "req-" + tag + "-2", 1, "站点C", "1.0", "备注"));
78	            throw new IllegalStateException("expected merge conflict");
79	        } catch (ApiException e) {
