        mergeNote("req-t-m2", "obs-t1", 1, "修改后的备注").andExpect(status().isOk());
        getTraverse("trv-10")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.edges[0].observationVersion").value(1))
                .andExpect(jsonPath("$.edges[0].correctedDx").value("0.980000"));
        // 用旧版本再次生成被拒绝（版本非当前）
